export function getFlowEmailEditorCopy(locale) {
  const loc = String(locale || "de").slice(0, 2).toLowerCase();
  const x = (en, tr, fr, es, it, de) => t(loc, en, tr, fr, es, it, de);
  return {
    template: x("Template", "Şablon", "Modèle", "Plantilla", "Template", "Vorlage"),
    append: x("Append", "Ekle", "Ajouter", "Añadir", "Aggiungi", "Anhängen"),
    modeVisual: x("Visual", "Görsel", "Visuel", "Visual", "Visuale", "Visuell"),
    modeHtml: x("HTML", "HTML", "HTML", "HTML", "HTML", "HTML"),
    modeText: x("Plain text", "Düz metin", "Texte brut", "Texto plano", "Testo semplice", "Klartext"),
    bold: x("Bold", "Kalın", "Gras", "Negrita", "Grassetto", "Fett"),
    italic: x("Italic", "İtalik", "Italique", "Cursiva", "Corsivo", "Kursiv"),
    list: x("List", "Liste", "Liste", "Lista", "Elenco", "Liste"),
  };
}
